        trace("snapshot_capture_begin")
        ui.postDelayed(captureTimeout,StageTransientTapPolicy.CAPTURE_BUDGET_MS)
        ui.postDelayed(lifetime,StageTransientTapPolicy.MAX_ATTEMPT_MS)
