        ui.removeCallbacks(captureTimeout);ui.removeCallbacks(commitTimeout);ui.removeCallbacks(lifetime)
        host.removeCallbacks(checkHandoff)
        removeVisual()
        trace("snapshot_end:"+result)
        onFinished()
    }
}

/** Two independently composed immutable cards. The parent records its
 * mask once; transform updates do not re-record the bitmaps or backdrop.
 * The optional platform RenderNodeAnimator drives the transforms on
 * RenderThread. Unsupported OEMs keep the exact same motion via UI
 * property transforms, not the removed multi-phase renderer.
 */
companion object {
    private fun motionBox(r:Rect)=StageSnapshotMotion.Box(
        r.left.toFloat(),r.top.toFloat(),r.right.toFloat(),r.bottom.toFloat())
    private fun planFlight(incoming:Bitmap,outgoing:Bitmap,slot:Rect,main:Rect,
                           others:List<Rect>,viewport:Rect)=StageSnapshotMotion.pairedFlights(
        motionBox(slot),motionBox(main),incoming.width,incoming.height,outgoing.width,outgoing.height,
        motionBox(viewport),others.map(::motionBox))
}
internal class FlightView(context:Context,private val incoming:Bitmap,private val outgoing:Bitmap,
                         slot:Rect,main:Rect,others:List<Rect>,private val backdrop:Drawable?,
                         viewport:Rect,planned:StageSnapshotMotion.PairFlight?=null):FrameLayout(context){
    private val excluded=others.map(::Rect)
    // Production always receives the precomputed worker result. The default
    // is retained for the isolated renderer's instrumentation harness.
    private val pair=planned?:planFlight(incoming,outgoing,slot,main,excluded,viewport)
    private val up=pair?.up
    private val down=pair?.down
    val safe=up!=null && down!=null
    private val slotRect=Rect(slot)
    private val mask=Path().apply{
        addRect(RectF(slot),Path.Direction.CW);addRect(RectF(main),Path.Direction.CW)
    }
    private var mainRevealed=false
    // Only invoked by the post-terminal, post-ACK handoff gate.
    // Remove BOTH the incoming preview and its opaque background in
    // the same View traversal. The outgoing preview remains in its slot.
    internal fun revealMain(){
        if(mainRevealed || released || progress!=1f)return
        mainRevealed=true
        upView.visibility=View.INVISIBLE
        mask.reset();mask.addRect(RectF(slotRect),Path.Direction.CW)
        invalidate()
    }
    private val upView=CardView(context,incoming,main)
    private val downView=CardView(context,outgoing,main)
    private val animations=mutableListOf<Animator>()
    var progress=0f
        set(value){
            field=value.coerceIn(0f,1f)
            up?.let{upView.place(it.pose(field))}
            down?.let{downView.place(it.pose(field))}
        }
    var drawn=false
        private set
    private var released=false
    init{
        importantForAccessibility=IMPORTANT_FOR_ACCESSIBILITY_NO_HIDE_DESCENDANTS
        isClickable=false
        setWillNotDraw(false)
        clipChildren=false;clipToPadding=false
        // Keep the tapped app visible when the cards cross. The old
        // main shrinks underneath instead of occluding the incoming card
        // until a sudden late z-reveal. Other slots retain strict clipping.
        addView(downView,LayoutParams(outgoing.width,outgoing.height,android.view.Gravity.TOP or android.view.Gravity.LEFT))
        addView(upView,LayoutParams(incoming.width,incoming.height,android.view.Gravity.TOP or android.view.Gravity.LEFT))
        progress=0f
    }
    override fun onDraw(canvas:Canvas){
        super.onDraw(canvas)
        if(released || !canvas.isHardwareAccelerated)return
        val save=canvas.save()
        excluded.forEach{canvas.clipOutRect(it)}
        canvas.clipPath(mask)
        canvas.drawColor(Color.rgb(12,14,21))
        backdrop?.setBounds(0,0,width,height);backdrop?.draw(canvas)
        canvas.restoreToCount(save)
    }

